    prices = json.loads(r[7]) if r[7] and r[7] != '{}' else {}
    flights.append({'id': r[0], 'airline': r[1], 'origin': r[2], 'dest': r[3], 'dep': r[4], 'arr': r[5], 'dur': r[6], 'prices': prices})

# Build route map
routes = {}
